import{_ as e,C as i,c as n,o as a,j as t,b as r,a0 as l,a as s,w as h,G as o,a1 as d}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Ein großartiger Teamplayer sein","description":"","frontmatter":{},"headers":[],"relativePath":"de/education/team-player/index.md","filePath":"de/education/team-player/index.md"}');const m=e({name:"de/education/team-player/index.md"},[["render",function(e,u,m,g,c,f){const k=i("Mermaid");return a(),n("div",null,[u[1]||(u[1]=t("h1",{id:"ein-großartiger-teamplayer-sein",tabindex:"-1"},[s("Ein großartiger Teamplayer sein "),t("a",{class:"header-anchor",href:"#ein-großartiger-teamplayer-sein","aria-label":'Permalink to "Ein großartiger Teamplayer sein"'},"​")],-1)),u[2]||(u[2]=t("p",null,"Pétanque wird oft in Teams gespielt – Doppel- oder Dreierteams. Individuelles Können ist wichtig, aber die Teamdynamik kann über Erfolg oder Misserfolg entscheiden. Die besten Teams sind nicht immer die technisch versiertesten – sie sind diejenigen, die am besten zusammenarbeiten.",-1)),u[3]||(u[3]=t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"Die große Idee"),t("p",null,[t("strong",null,"Die besten Teams sind nicht immer die technisch versiertesten – sie sind diejenigen, die am besten zusammenarbeiten."),s(" Bescheidenheit, Ehrgeiz und emotionale Intelligenz machen dich zu einem großartigen Teammitglied.")])],-1)),(a(),r(d,null,{default:h(()=>[o(k,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BToller%20Teamkollege%5D%20--%3E%20B%5BBescheiden%5D%0A%20%20%20%20A%20--%3E%20C%5BHungrig%5D%0A%20%20%20%20A%20--%3E%20D%5BSchlau%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BTeamerfolg%5D%0A%20%20%20%20C%20--%3E%20E%0A%20%20%20%20D%20--%3E%20E%0A%0A%20%20%20%20E%20--%3E%20F%5BMeisterschaftsleistung%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20D%20fill%3A%23f3e5f5%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:h(()=>[...u[0]||(u[0]=[s(" Loading... ",-1)])]),_:1})),u[4]||(u[4]=l('<h2 id="was-zeichnet-einen-großartigen-teamkollegen-aus" tabindex="-1">Was zeichnet einen großartigen Teamkollegen aus? <a class="header-anchor" href="#was-zeichnet-einen-großartigen-teamkollegen-aus" aria-label="Permalink to &quot;Was zeichnet einen großartigen Teamkollegen aus?&quot;">​</a></h2><p>Forschung und Erfahrung weisen auf drei Schlüsseleigenschaften hin:</p><h3 id="_1-bescheiden" tabindex="-1">1. Bescheiden <a class="header-anchor" href="#_1-bescheiden" aria-label="Permalink to &quot;1. Bescheiden&quot;">​</a></h3><ul><li>Stellt den Erfolg des Teams über den persönlichen Ruhm.</li><li>Würdigt die Beiträge anderer</li><li>Gibt Fehler ohne Ausreden zu.</li><li>Offen für Feedback und Lernen</li><li>Er muss nicht der Star sein.</li></ul><h3 id="_2-hungrig" tabindex="-1">2. Hungrig <a class="header-anchor" href="#_2-hungrig" aria-label="Permalink to &quot;2. Hungrig&quot;">​</a></h3><ul><li>Selbstmotiviert und zielstrebig</li><li>Erledigt die Arbeit, ohne dazu aufgefordert zu werden.</li><li>Wir sind stets bestrebt, uns zu verbessern</li><li>Bringt Energie ins Team</li><li>Verlässt sich nicht auf Talent.</li></ul><h3 id="_3-intelligent-emotional" tabindex="-1">3. Intelligent (emotional) <a class="header-anchor" href="#_3-intelligent-emotional" aria-label="Permalink to &quot;3. Intelligent (emotional)&quot;">​</a></h3><ul><li>Kann Situationen und Menschen gut einschätzen</li><li>Weiß, wann er sprechen und wann er zuhören soll.</li><li>Sie kontrollieren ihre eigenen Emotionen</li><li>Unterstützt Teammitglieder angemessen</li><li>Geht konstruktiv mit Konflikten um</li></ul><h2 id="die-grundlagen-fur-den-erfolg-eines-teams" tabindex="-1">Die Grundlagen für den Erfolg eines Teams <a class="header-anchor" href="#die-grundlagen-fur-den-erfolg-eines-teams" aria-label="Permalink to &quot;Die Grundlagen für den Erfolg eines Teams&quot;">​</a></h2><h3 id="gemeinsame-ziele-und-vision" tabindex="-1">Gemeinsame Ziele und Vision <a class="header-anchor" href="#gemeinsame-ziele-und-vision" aria-label="Permalink to &quot;Gemeinsame Ziele und Vision&quot;">​</a></h3><p>Starke Teams zeichnen sich durch Folgendes aus:</p><ul><li>Klare, vereinbarte Ziele</li><li>Individuelle Ziele im Einklang mit den Teamzielen</li><li>Gemeinsames Verständnis davon, wie Erfolg aussieht</li><li>Engagement für die gemeinsame Mission</li></ul><p><strong>Fragen zur Besprechung mit Ihrem Team:</strong></p><ul><li>Was wollen wir gemeinsam erreichen?</li><li>Wie sieht Erfolg für uns aus?</li><li>Wie tragen unsere individuellen Ziele zum Erfolg des Teams bei?</li></ul><h3 id="effektive-kommunikation" tabindex="-1">Effektive Kommunikation <a class="header-anchor" href="#effektive-kommunikation" aria-label="Permalink to &quot;Effektive Kommunikation&quot;">​</a></h3><p>Kommunikation ist das Lebenselixier der Teamleistung.</p><p><strong>Gute Teamkommunikation:</strong></p><ul><li>Offen und ehrlich</li><li>Respektvoll, auch bei Meinungsverschiedenheiten.</li><li>Klar und präzise</li><li>Zwei-Wege-Kommunikation (Sprechen UND Hören)</li><li>Zeitnah (die richtigen Informationen zur richtigen Zeit)</li></ul><p><strong>Während der Spiele:</strong></p><ul><li>Besprechen Sie die Strategie vor jedem Ende</li><li>Beobachtungen zum Gelände und zu den Gegnern austauschen</li><li>Koordinieren, wer wann wirft.</li><li>Unterstützt euch gegenseitig nach Würfen (ob gut oder schlecht).</li></ul><h3 id="vertrauen-und-respekt" tabindex="-1">Vertrauen und Respekt <a class="header-anchor" href="#vertrauen-und-respekt" aria-label="Permalink to &quot;Vertrauen und Respekt&quot;">​</a></h3><p>Ohne Vertrauen zerfallen Teams unter Druck.</p><p><strong>Vertrauensbildung:</strong></p><ul><li>Sei zuverlässig (halte deine Versprechen).</li><li>Sei kompetent (erledige deine Arbeit gut).</li><li>Sei ehrlich (auch wenn es schwerfällt).</li><li>Verletzlichkeit zeigen (Schwierigkeiten eingestehen)</li><li>Unterstütze andere konsequent</li></ul><p><strong>Respekt zeigen:</strong></p><ul><li>Wertschätzen Sie den Beitrag jedes Einzelnen</li><li>Hören Sie sich verschiedene Perspektiven an.</li><li>Würdigen Sie den Einsatz, nicht nur die Ergebnisse.</li><li>Behandeln Sie die Rolle jedes Einzelnen als wichtig</li></ul><h3 id="klare-rollen" tabindex="-1">Klare Rollen <a class="header-anchor" href="#klare-rollen" aria-label="Permalink to &quot;Klare Rollen&quot;">​</a></h3><p>Jeder sollte Folgendes verstehen:</p><ul><li>Ihre Hauptaufgaben</li><li>Wie sie zum Team beitragen</li><li>Worauf andere sie hoffen</li><li>Wann man die Initiative ergreifen und wann man sich zurückziehen sollte</li></ul><p><strong>Im Dreiergespann:</strong></p><table tabindex="0"><thead><tr><th>Rolle</th><th>Hauptfokus</th><th>Wichtigste Eigenschaften</th></tr></thead><tbody><tr><td>Zeiger</td><td>Platziere die Boules in der Nähe des Ziels.</td><td>Präzision, Konsistenz</td></tr><tr><td>Mitte</td><td>Der Situation anpassen</td><td>Vielseitigkeit, Lesespiel</td></tr><tr><td>Schütze</td><td>Gegnerische Boules entfernen</td><td>Genauigkeit unter Druck</td></tr></tbody></table><p>Die Rollen können flexibel gestaltet werden, aber Klarheit ist hilfreich.</p><h2 id="teamdynamik-wahrend-des-wettbewerbs" tabindex="-1">Teamdynamik während des Wettbewerbs <a class="header-anchor" href="#teamdynamik-wahrend-des-wettbewerbs" aria-label="Permalink to &quot;Teamdynamik während des Wettbewerbs&quot;">​</a></h2><h3 id="vor-dem-spiel" tabindex="-1">Vor dem Spiel <a class="header-anchor" href="#vor-dem-spiel" aria-label="Permalink to &quot;Vor dem Spiel&quot;">​</a></h3><ul><li>Gemeinsam ankommen, gemeinsam aufwärmen</li><li>Allgemeine Strategie besprechen</li><li>Den Ton angeben (positiv, fokussiert)</li><li>Erkundige dich, wie es allen geht.</li></ul><h3 id="wahrend-des-spiels" tabindex="-1">Während des Spiels <a class="header-anchor" href="#wahrend-des-spiels" aria-label="Permalink to &quot;Während des Spiels&quot;">​</a></h3><ul><li>Kommunikation zwischen den Enden</li><li>Bleiben Sie unabhängig vom Ergebnis positiv.</li><li>Unterstützt euch gegenseitig nach Fehlern</li><li>Gemeinsam Erfolge feiern (kurz)</li><li>Konzentriere dich auf den Prozess, nicht auf das Ergebnis.</li></ul><h3 id="nach-fehlern" tabindex="-1">Nach Fehlern <a class="header-anchor" href="#nach-fehlern" aria-label="Permalink to &quot;Nach Fehlern&quot;">​</a></h3><p>Was Sie NICHT tun sollten:</p><ul><li>Zeigen Sie Ihre Frustration sichtbar</li><li>Kritisieren oder beschuldigen</li><li>Sich zurückziehen oder schweigen</li><li>Denken Sie darüber nach, was passiert ist.</li></ul><p>Was zu tun:</p><ul><li>Schnelle Bestätigung („kein Problem“)</li><li>Konzentriere dich auf den nächsten Wurf.</li><li>Achten Sie auf eine positive Körpersprache.</li><li>Vertraue darauf, dass dein Teamkollege sich erholt.</li></ul><h3 id="nach-dem-spiel" tabindex="-1">Nach dem Spiel <a class="header-anchor" href="#nach-dem-spiel" aria-label="Permalink to &quot;Nach dem Spiel&quot;">​</a></h3><ul><li>Gemeinsame Nachbesprechung (was funktioniert hat, was nicht)</li><li>Individuelle Beiträge anerkennen</li><li>Besprechen Sie Verbesserungen für das nächste Mal</li><li>Beziehungen unabhängig vom Ergebnis pflegen</li></ul><h2 id="kommunikationsmuster" tabindex="-1">Kommunikationsmuster <a class="header-anchor" href="#kommunikationsmuster" aria-label="Permalink to &quot;Kommunikationsmuster&quot;">​</a></h2><h3 id="konstruktives-feedback" tabindex="-1">Konstruktives Feedback <a class="header-anchor" href="#konstruktives-feedback" aria-label="Permalink to &quot;Konstruktives Feedback&quot;">​</a></h3><p><strong>Schlecht:</strong> &quot;Du verfehlst diese Schüsse immer wieder.&quot; <strong>Besser:</strong> „Mir ist aufgefallen, dass die Schüsse nach links gehen – möchten Sie Ihre Haltung anpassen?“</p><h3 id="unterstutzende-reaktion-auf-fehler" tabindex="-1">Unterstützende Reaktion auf Fehler <a class="header-anchor" href="#unterstutzende-reaktion-auf-fehler" aria-label="Permalink to &quot;Unterstützende Reaktion auf Fehler&quot;">​</a></h3><p><strong>Schlecht:</strong> <em>Schweigen oder sichtbare Frustration</em><strong>Besser:</strong> „Schwierige Frage. Du bist als Nächste dran.“</p><h3 id="strategische-diskussion" tabindex="-1">Strategische Diskussion <a class="header-anchor" href="#strategische-diskussion" aria-label="Permalink to &quot;Strategische Diskussion&quot;">​</a></h3><p><strong>Schlecht:</strong> &quot;Schieß einfach drauf&quot; <strong>Besser:</strong> „Was meinst du – mit dem Finger blocken oder versuchen zu schießen? Ich sehe Vor- und Nachteile auf beiden Wegen.“</p><h2 id="aufbau-einer-teamkultur" tabindex="-1">Aufbau einer Teamkultur <a class="header-anchor" href="#aufbau-einer-teamkultur" aria-label="Permalink to &quot;Aufbau einer Teamkultur&quot;">​</a></h2><p>Großartige Teams entwickeln Gemeinsamkeiten:</p><ul><li><strong>Werte:</strong> Wofür wir stehen</li><li><strong>Normen:</strong> Unser Verhalten</li><li><strong>Sprache:</strong> Wie wir kommunizieren</li><li><strong>Rituale:</strong> Was wir gemeinsam tun</li></ul><p><strong>Beispiele:</strong></p><ul><li>Vor und nach dem Essen immer die Hand schütteln</li><li>Konkrete Ermutigungsformulierungen</li><li>gemeinsames Ritual vor dem Spiel</li><li>Mahlzeit oder Getränk nach dem Spiel</li></ul><h2 id="in-diesem-abschnitt" tabindex="-1">In diesem Abschnitt <a class="header-anchor" href="#in-diesem-abschnitt" aria-label="Permalink to &quot;In diesem Abschnitt&quot;">​</a></h2><ul><li><strong><a href="/en/education/team-player/communication">Teamkommunikation</a></strong> – Ausführlicher Leitfaden für effektive Kommunikation</li></ul><h2 id="wichtigste-erkenntnis" tabindex="-1">Wichtigste Erkenntnis <a class="header-anchor" href="#wichtigste-erkenntnis" aria-label="Permalink to &quot;Wichtigste Erkenntnis&quot;">​</a></h2><blockquote><p>Ihr Team ist nur so stark wie seine schwächste Beziehung, nicht wie sein schwächstes Mitglied.</p></blockquote><p>Investiere in deine Teammitglieder. Baue Vertrauen auf. Kommuniziere gut. Gewinnt gemeinsam.</p>',61))])}]]);export{u as __pageData,m as default};
